package httpapi

import("errors";"fmt";"net/http";"time";"github.com/Loccao102/LocCaoEnglish/backend/internal/engine";"github.com/Loccao102/LocCaoEnglish/backend/internal/model";"github.com/Loccao102/LocCaoEnglish/backend/internal/store")
func(s *Server)registerPlatformRoutes(mux *http.ServeMux){mux.HandleFunc("GET /v1/courses",s.courses);mux.HandleFunc("GET /v1/courses/{slug}",s.course);mux.HandleFunc("POST /v1/courses/{slug}/enroll",s.enrollCourse);mux.HandleFunc("GET /v1/courses/{slug}/progress",s.courseProgress);mux.HandleFunc("GET /v1/player/profile",s.playerProfile);mux.HandleFunc("PUT /v1/player/profile",s.savePlayerProfile);mux.HandleFunc("GET /v1/player/questline",s.playerQuestline);mux.HandleFunc("GET /v1/admin/analytics",s.adminAnalytics);mux.HandleFunc("GET /v1/social/events",s.socialEvents);s.registerProgressionRoutes(mux)}
func(s *Server)courses(w http.ResponseWriter,r *http.Request){items,err:=s.store.ListCourses(r.Context());if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)course(w http.ResponseWriter,r *http.Request){item,err:=s.store.GetCourse(r.Context(),r.PathValue("slug"));if errors.Is(err,store.ErrNotFound){problem(w,404,"course not found");return};if err!=nil{problem(w,500,err.Error());return};write(w,200,item)};func(s *Server)enrollCourse(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};p,err:=s.store.EnrollCourse(r.Context(),id,r.PathValue("slug"));if errors.Is(err,store.ErrNotFound){problem(w,404,"course not found");return};if err!=nil{problem(w,500,err.Error());return};write(w,200,p)};func(s *Server)courseProgress(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};p,err:=s.store.CourseProgress(r.Context(),id,r.PathValue("slug"));if errors.Is(err,store.ErrNotFound){problem(w,404,"course not found");return};if err!=nil{problem(w,500,err.Error());return};write(w,200,p)}
func(s *Server)playerProfile(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};p,err:=s.store.GetPlayerProfile(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};write(w,200,p)};func(s *Server)savePlayerProfile(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};var in model.PlayerProfile;if!decode(w,r,&in){return};p,err:=s.store.SavePlayerProfile(r.Context(),id,in);if err!=nil{problem(w,400,err.Error());return};write(w,200,p)};func(s *Server)playerQuestline(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};skills,err:=s.store.Skills(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};reviews,_:=s.store.ReviewQueue(r.Context(),id,20);profile,err:=s.store.GetPlayerProfile(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};write(w,200,engine.BuildPlanForProfile(skills,reviews,profile))}
func(s *Server)adminAnalytics(w http.ResponseWriter,r *http.Request){if _,ok:=s.requireRole(w,r,"teacher","admin");!ok{return};data,err:=s.store.Analytics(r.Context());if err!=nil{problem(w,500,err.Error());return};write(w,200,data)}
func(s *Server)socialEvents(w http.ResponseWriter,r *http.Request){flusher,ok:=w.(http.Flusher);if!ok{problem(w,500,"streaming is not supported");return};w.Header().Set("Content-Type","text/event-stream");w.Header().Set("Cache-Control","no-cache, no-transform");w.Header().Set("Connection","keep-alive");w.Header().Set("X-Accel-Buffering","no");events,closeSub:=s.social.Subscribe(r.Context());defer closeSub();fmt.Fprintf(w,"data: {\"type\":\"ready\",\"mode\":\"%s\"}\n\n",s.social.Mode());flusher.Flush();heartbeat:=time.NewTicker(15*time.Second);defer heartbeat.Stop();lifetime:=time.NewTimer(50*time.Second);defer lifetime.Stop();for{select{case<-r.Context().Done():return;case<-lifetime.C:return;case<-heartbeat.C:fmt.Fprint(w,": heartbeat\n\n");flusher.Flush();case event,ok:=<-events:if!ok{return};fmt.Fprintf(w,"data: %s\n\n",event);flusher.Flush()}}}
